negativeExample:
class Test {
    void noMatch() {
        String s = "hello world";

        // Case 1: indexOf used to get an index (not a boolean comparison)
        int index = s.indexOf("o");
        System.out.println("Index of 'o': " + index);

        // Case 2: indexOf compared to something other than -1 (semantically different checks)
        if (s.indexOf("hello") == 0) {
            System.out.println("Starts with 'hello'");
        }
        if (s.indexOf("world") > 0) {
            System.out.println("Contains 'world' not at start");
        }

        // Case 3: indexOf with char literal (not a StringLiteral as per guard)
        if (s.indexOf('w') != -1) {
            System.out.println("Contains 'w'");
        }
        char c = 'x';
        if (s.indexOf(c) != -1) { // Argument is a variable, not a StringLiteral
            System.out.println("Contains 'x'");
        }

        // Case 4: Not a String receiver (fails instanceof guard)
        StringBuilder sb = new StringBuilder("test");
        if (sb.indexOf("es") != -1) {
            System.out.println("StringBuilder contains 'es'");
        }
    }
}
